class Clock:
    def __init__(self):
        self.value = 0.0

    def __call__(self):
        return self.value


class Response:
    def __init__(self, url, payload, clock):
        self.url, self.payload, self.clock = url, payload, clock
        self.headers = {"Content-Length": str(len(payload))}
        self.status = 200
        self.position = 0
        self.socket_timeouts = []
        self.read_tick = .01
        self.fp = SimpleNamespace(raw=SimpleNamespace(_sock=SimpleNamespace(settimeout=self.socket_timeouts.append)))

    def __enter__(self):
        return self

    def __exit__(self, *args):
        return False

    def geturl(self):
        return self.url

    def read1(self, size):
        self.clock.value += self.read_tick
        block = self.payload[self.position:self.position + min(size, 7)]
        self.position += len(block)
        return block


class Image:
    dtype = "uint8"

    def __init__(self, pixel, width=3, height=2):
        self.pixel = pixel
        self.shape = (height, width, 3)

    def __getitem__(self, slices):
        vertical, horizontal = slices
        return Image(self.pixel, horizontal.stop - horizontal.start, vertical.stop - vertical.start)


class Fixture:
    def __init__(self):
        self.clock = Clock()
        self.requests, self.responses, self.calls, self.decodes = [], [], [], []
        self.payloads, self.images = {}, {}
        self.install_returncode = 0
        self.ocr_returncode = 0
        self.version = evidence.exact._TESSERACT_WINDOWS_VERSION_LINE
        self.fail_url = None
        self.late_download = False
        self.late_install = False
        self.install_clock = None

    def opener(self, request, *, timeout):
        url = request.full_url
        self.requests.append((url, timeout))
        if self.fail_url == url:
            raise HTTPError(url, 429, "generated rate limit", {}, None)
        response = Response(url, self.payloads[url], self.clock)
        if self.late_download:
            response.read_tick = 211.0
        self.responses.append(response)
        return response

    def runner(self, args, **kwargs):
        self.calls.append((list(args), dict(kwargs)))
        self.clock.value += 1.0
        if args[1] == "/S":
            install_dir = Path(args[2][3:])
            install_dir.mkdir()
            (install_dir / "tesseract.exe").write_bytes(b"generated-executable")
            if self.late_install:
                self.clock.value = 211.0
            if self.install_clock is not None:
                self.clock.value = self.install_clock
            return subprocess.CompletedProcess(args, self.install_returncode, stdout=b"", stderr=b"")
        if args[-1] == "--version":
            return subprocess.CompletedProcess(args, 0, stdout=(self.version + "\n").encode(), stderr=b"")
        psm = args[args.index("--psm") + 1]
        index = sum(call[0][1] == "stdin" for call in self.calls) - 1
        texts = {("7", 0): "AB1", ("13", 0): "AB1", ("7", 1): "CD9",
                 ("13", 1): None, ("7", 2): "EF?3", ("13", 2): "EF3"}
        text = texts[psm, index // 2]
        tsv = "level\tconf\ttext\n" + ("1\t-1\t\n" if text is None else f"5\t90\t{text}\n")
        return subprocess.CompletedProcess(args, self.ocr_returncode, stdout=tsv.encode(), stderr=b"")

    @contextmanager
    def environment(self, root):
        with ExitStack() as stack:
            stack.enter_context(mock.patch.object(evidence, "_require_hosted_windows"))
            stack.enter_context(mock.patch.dict(os.environ, {"RUNNER_TEMP": str(root)}))
            for index, (_, module) in enumerate(evidence._SOURCES):
                payload = f"generated-source-{index}".encode()
                rgb = bytes((index + 3, index + 2, index + 1)) * 2
                values = {"_SOURCE_SIZE": len(payload), "_SOURCE_SHA1": hashlib.sha1(payload).hexdigest(),
                          "_SOURCE_SHA256": hashlib.sha256(payload).hexdigest(),
                          "_SOURCE_WIDTH": 3, "_SOURCE_HEIGHT": 2,
                          "_EXPECTED_TEXT": ("AB1", "CD2", "EF3")[index],
                          "_CROP_RGB24_SHA256": hashlib.sha256(rgb).hexdigest()}
                values["_PLATE_BOX_PX" if module is evidence.exact else "_PLATE_TEXT_BOX_PX"] = (0, 0, 2, 1)
                for key, value in values.items():
                    stack.enter_context(mock.patch.object(module, key, value))
                self.payloads[module._SOURCE_URL] = payload
                self.images[payload] = Image(bytes((index + 1, index + 2, index + 3)))
            installer, model = b"generated-installer", b"generated-traineddata"
            blob = evidence.exact._git_blob_sha1(model)
            for key, value in {"_TESSERACT_INSTALLER_SIZE": len(installer),
                               "_TESSERACT_INSTALLER_SHA256": hashlib.sha256(installer).hexdigest(),
                               "_TESSDATA_SIZE": len(model), "_TESSDATA_GIT_BLOB_SHA1": blob}.items():
                stack.enter_context(mock.patch.object(evidence.exact, key, value))
            stack.enter_context(mock.patch.object(lpr_ocr, "_TESSDATA_ENG_SIZE", len(model)))
            stack.enter_context(mock.patch.object(lpr_ocr, "_TESSDATA_ENG_GIT_BLOB_SHA1", blob))
            self.payloads[evidence.exact._TESSERACT_INSTALLER_URL] = installer
            self.payloads[evidence.exact._TESSDATA_URL] = model
            stack.enter_context(mock.patch.object(evidence, "_PAYLOAD_BYTES", sum(map(len, self.payloads.values()))))

            def decode(payload, mode):
                self.decodes.append(payload)
                return self.images[payload]

            def convert(image, mode):
                rgb = image.pixel[::-1] * (image.shape[0] * image.shape[1])
                return SimpleNamespace(tobytes=lambda **kwargs: rgb)

            cv2 = SimpleNamespace(__version__="4.12.0", IMREAD_COLOR=1, COLOR_BGR2RGB=4,
                                  imdecode=decode, cvtColor=convert)
            numpy = SimpleNamespace(__version__="2.2.6", uint8="uint8", frombuffer=lambda value, **kwargs: value)
            stack.enter_context(mock.patch.dict(sys.modules, {"cv2": cv2, "numpy": numpy}))
            yield self

    def run(self, root):
        with redirect_stdout(io.StringIO()):
            return evidence.run(root / "serial", opener=self.opener, runner=self.runner, clock=self.clock)


class SerialComparisonTests(unittest.TestCase):
    def test_frozen_plan_scope_settings_and_source_code_bindings(self):
        plan = evidence.comparison_plan()
        self.assertEqual(plan["payload_bytes"], 39_945_587)
        self.assertEqual(plan["evidence_elapsed_limit_seconds"], 210)
        self.assertIn("cooperative", plan["bound_semantics"]["elapsed_budget"])
        self.assertIn("inactivity", plan["bound_semantics"]["http_timeout"])
        self.assertEqual(plan["bound_semantics"]["hard_hosted_job_limit_seconds"], 300)
        self.assertEqual([item["expected_text"] for item in plan["sources"]], ["MPR318", "354AVV", "CPU4704"])
        self.assertEqual([item["crop_rgb24_bytes"] for item in plan["sources"]], [2403000, 1092750, 8736000])
        first, second = [dict(item) for item in plan["profiles"]]
        self.assertEqual(first.pop("tesseract_psm"), 7)
        self.assertEqual(second.pop("tesseract_psm"), 13)
        self.assertEqual(first, second)
        self.assertEqual(first["min_ocr_confidence"], 0.0)
        self.assertFalse(plan["historical_gray_otsu_is_paired_control"])
        for name, digest in plan["project_source_sha256"].items():
            self.assertEqual(digest, hashlib.sha256(Path(evidence.__file__).with_name(name).read_bytes()).hexdigest())

    def test_actual_orchestration_same_pixels_once_per_asset_and_result_conservation(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary).resolve()
            sentinel = root / "unrelated"
            sentinel.write_text("keep")
            fixture = Fixture()
            with fixture.environment(root):
                report = fixture.run(root)
                self.assertEqual([url for url, _ in fixture.requests],
                                 [module._SOURCE_URL for _, module in evidence._SOURCES]
                                 + [evidence.exact._TESSERACT_INSTALLER_URL, evidence.exact._TESSDATA_URL])
            self.assertEqual(len(fixture.decodes), 3)
            self.assertEqual(len(fixture.calls), 9)
            self.assertEqual((report["installations"], report["version_probes"], report["ocr_calls"]), (1, 2, 6))
            ocr = [item for item in fixture.calls if item[0][1] == "stdin"]
            for index in range(0, 6, 2):
                left, right = ocr[index:index + 2]
                self.assertIs(left[1]["input"], right[1]["input"])
                changed = list(left[0])
                changed[changed.index("--psm") + 1] = "13"
                self.assertEqual(changed, right[0])
                self.assertEqual(left[1]["input"].split(b"\n", 3)[-1], bytes((index // 2 + 3, index // 2 + 2, index // 2 + 1)) * 2)
            baseline, candidate = report["baseline_psm7"], report["candidate_psm13"]
            self.assertEqual((baseline["exact_reads"], baseline["incorrect_reads"], baseline["abstentions"], baseline["character_errors"]), (1, 1, 1, 4))
            self.assertEqual((candidate["exact_reads"], candidate["incorrect_reads"], candidate["abstentions"], candidate["character_errors"]), (2, 0, 1, 3))
            for result in (baseline, candidate):
                self.assertEqual(result["cases"], result["exact_reads"] + result["incorrect_reads"] + result["abstentions"])
                self.assertEqual(result["reference_characters"], 9)
                self.assertIsNone(result["false_positive_rate"])
            self.assertEqual(report["delta_candidate_minus_baseline"]["character_errors"], -1)
            self.assertTrue(report["temporary_assets_removed"])
            self.assertFalse((root / "serial").exists())
            self.assertEqual(sentinel.read_text(), "keep")
            for key in ("accuracy_gate_passed", "default_promotion", "held_out", "commercial_accuracy_claim", "performance_claim"):
                self.assertFalse(report[key])
            encoded = json.dumps(report)
            self.assertNotIn(str(root), encoded)
            self.assertNotIn("generated-source", encoded)
            self.assertEqual(report["plan_sha256"], hashlib.sha256(evidence._canonical(report["plan"])).hexdigest())
            self.assertEqual(report["bound_semantics"], report["plan"]["bound_semantics"])

    def test_identity_or_native_failure_cleans_and_emits_no_complete_report(self):
        for failure in ("source", "crop", "installer_hash", "model_hash", "install", "version", "ocr"):
            with self.subTest(failure=failure), tempfile.TemporaryDirectory() as temporary:
                root, fixture = Path(temporary).resolve(), Fixture()
                with fixture.environment(root):
                    if failure == "source":
                        url = evidence.sc._SOURCE_URL
                        fixture.payloads[url] = b"x" * len(fixture.payloads[url])
                    elif failure == "crop":
                        fixture.images[fixture.payloads[evidence.exact._SOURCE_URL]].pixel = b"\x00\x00\x00"
                    elif failure in ("installer_hash", "model_hash"):
                        url = evidence.exact._TESSERACT_INSTALLER_URL if failure == "installer_hash" else evidence.exact._TESSDATA_URL
                        fixture.payloads[url] = b"x" * len(fixture.payloads[url])
                    elif failure == "install":
                        fixture.install_returncode = 1
                    elif failure == "version":
                        fixture.version = "tesseract v5.5.4"
                    else:
                        fixture.ocr_returncode = 1
                    with self.assertRaises((RuntimeError, ValueError)):
                        fixture.run(root)
                    if failure == "source":
                        self.assertEqual(len(fixture.requests), 2)
                        self.assertFalse(fixture.calls)
                    if failure == "crop":
                        self.assertEqual(len(fixture.requests), 1)
                        self.assertFalse(fixture.calls)
                self.assertFalse((root / "serial").exists())

