    def test_network_deadline_reduces_every_read_socket_timeout(self):
        clock = Clock()
        deadline = evidence._Deadline(clock)
        clock.value = 190
        response = Response("https://upload.wikimedia.org/fake", b"a" * 20, clock)
        response.read_tick = 6
        with self.assertRaises(TimeoutError):
            evidence._download(response.url, size=20, hosts=frozenset({"upload.wikimedia.org"}),
                               deadline=deadline, opener=lambda *args, **kwargs: response)
        self.assertEqual(response.socket_timeouts, [15, 9, 3])

    def test_actual_http_response_can_close_socket_on_last_declared_byte(self):
        class MemorySocket:
            closed = False

            def makefile(self, mode):
                return io.BufferedReader(MemoryRaw(self))

            def settimeout(self, timeout):
                if self.closed:
                    raise OSError(9, "generated closed descriptor")

        class MemoryRaw(io.RawIOBase):
            def __init__(self, sock):
                self._sock = sock
                self.stream = io.BytesIO(b"HTTP/1.1 200 OK\r\nContent-Length: 3\r\n\r\nabc")

            def readable(self):
                return True

            def readinto(self, buffer):
                block = self.stream.read(len(buffer))
                buffer[:len(block)] = block
                return len(block)

            def close(self):
                self._sock.closed = True
                super().close()

        sock = MemorySocket()
        url = "https://upload.wikimedia.org/generated"
        response = http.client.HTTPResponse(sock, method="GET", url=url)
        response.begin()
        # urllib assigns this attribute after constructing HTTPResponse.
        response.url = url
        result = evidence._download(url, size=3, hosts=frozenset({"upload.wikimedia.org"}),
                                    deadline=evidence._Deadline(Clock()), opener=lambda *args, **kwargs: response)
        self.assertEqual(result, b"abc")
        self.assertTrue(sock.closed)

    def test_subprocess_timeout_is_capped_by_remaining_shared_budget(self):
        with tempfile.TemporaryDirectory() as temporary:
            root, fixture = Path(temporary).resolve(), Fixture()
            with fixture.environment(root):
                fixture.install_clock = 195
                report = fixture.run(root)
            ocr_timeouts = [kwargs["timeout"] for args, kwargs in fixture.calls if args[1] == "stdin"]
            self.assertEqual(ocr_timeouts, [9, 7, 6, 5, 4, 3])
            self.assertLess(report["evidence_elapsed_seconds"], 210)

    def test_stream_scope_size_and_timeout_interface_are_fail_closed(self):
        for problem in ("redirect", "declared_size", "missing_length", "chunked", "overflow", "short", "socket", "read1"):
            with self.subTest(problem=problem):
                clock = Clock()
                response = Response("https://upload.wikimedia.org/fake", b"abc", clock)
                if problem == "redirect":
                    response.url = "https://unreviewed.example/fake"
                elif problem == "declared_size":
                    response.headers["Content-Length"] = "4"
                elif problem == "missing_length":
                    del response.headers["Content-Length"]
                elif problem == "chunked":
                    response.headers["Transfer-Encoding"] = "chunked"
                elif problem == "overflow":
                    response.payload = b"abcd"
                elif problem == "short":
                    response.payload = b"ab"
                elif problem == "socket":
                    response.fp = None
                else:
                    response.read1 = None
                with self.assertRaises(RuntimeError):
                    evidence._download("https://upload.wikimedia.org/fake", size=3,
                                       hosts=frozenset({"upload.wikimedia.org"}), deadline=evidence._Deadline(clock),
                                       opener=lambda *args, **kwargs: response)
                if problem in ("chunked", "missing_length"):
                    self.assertEqual(response.position, 0)

    def test_hosted_guard_accepts_only_the_dedicated_windows_pr_lane(self):
        valid = {"GITHUB_ACTIONS": "true", "RUNNER_ENVIRONMENT": "github-hosted", "RUNNER_OS": "Windows",
                 "GITHUB_REPOSITORY": "mkurtgerald/Analytics-lab", "GITHUB_EVENT_NAME": "pull_request",
                 "GITHUB_HEAD_REF": "evidence/lpr-serial-compare-generated"}
        with mock.patch.object(evidence.os, "name", "nt"), mock.patch.dict(os.environ, valid, clear=True):
            evidence._require_hosted_windows()
            for key, value in (("GITHUB_ACTIONS", "false"), ("RUNNER_ENVIRONMENT", "self-hosted"),
                               ("RUNNER_OS", "Linux"), ("GITHUB_REPOSITORY", "elsewhere/repo"),
                               ("GITHUB_EVENT_NAME", "push"), ("GITHUB_HEAD_REF", "evidence/lpr-ocr-exact-old")):
                with self.subTest(key=key), mock.patch.dict(os.environ, {key: value}), self.assertRaises(RuntimeError):
                    evidence._require_hosted_windows()

    def test_decoder_runtime_mismatch_fails_before_assets(self):
        for cv_version, np_version in (("4.11.0", "2.2.6"), ("4.12.0", "2.3.0")):
            with self.subTest(cv=cv_version, np=np_version), tempfile.TemporaryDirectory() as temporary:
                root, fixture = Path(temporary).resolve(), Fixture()
                with fixture.environment(root):
                    sys.modules["cv2"].__version__ = cv_version
                    sys.modules["numpy"].__version__ = np_version
                    with self.assertRaises(RuntimeError):
                        fixture.run(root)
                self.assertFalse(fixture.requests)
                self.assertFalse((root / "serial").exists())

    def test_unhosted_execution_and_unsafe_or_existing_work_directory_rejected(self):
        with mock.patch.dict(os.environ, {}, clear=True), self.assertRaises(RuntimeError):
            evidence._require_hosted_windows()
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary).resolve()
            (root / "existing").mkdir()
            with mock.patch.dict(os.environ, {"RUNNER_TEMP": str(root)}):
                for path in (root, root.parent / "outside", root / "existing", root / "missing" / "nested"):
                    with self.subTest(path=path), self.assertRaises(RuntimeError):
                        evidence._work_directory(path)
                if os.name != "nt":
                    (root / "link").symlink_to(root / "existing", target_is_directory=True)
                    with self.assertRaises(RuntimeError):
                        evidence._work_directory(root / "link")

    def test_plan_scope_and_budget_reject_before_acquisition(self):
        for problem in ("budget", "scope"):
            with self.subTest(problem=problem), tempfile.TemporaryDirectory() as temporary:
                root, fixture = Path(temporary).resolve(), Fixture()
                with fixture.environment(root):
                    target = "_PAYLOAD_BYTES" if problem == "budget" else "_SOURCES"
                    value = evidence._PAYLOAD_BYTES + 1 if problem == "budget" else tuple(reversed(evidence._SOURCES))
                    with mock.patch.object(evidence, target, value), self.assertRaises(RuntimeError):
                        fixture.run(root)
                self.assertFalse(fixture.requests)
                self.assertFalse((root / "serial").exists())

    def test_cleanup_still_occurs_if_progress_output_fails(self):
        with tempfile.TemporaryDirectory() as temporary:
            root, fixture = Path(temporary).resolve(), Fixture()
            with fixture.environment(root):
                def phase(name, **kwargs):
                    if name == "cleanup":
                        raise OSError("generated output failure")
                with mock.patch.object(evidence, "_phase", side_effect=phase), self.assertRaises(OSError):
                    fixture.run(root)
            self.assertFalse((root / "serial").exists())

